import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load texture via cached loader
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Create material - MeshBasicMaterial for unlit, static composition
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create plane geometry with aspect ratio 512:320 = 1.6:1
  const width = 2.0;
  const height = 1.25;
  const geometry = new THREE.PlaneGeometry(width, height);

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply cinematic primitives if specified
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    }
  }

  // Cleanup: dispose all resources and kill animations
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();

    gsap.killTweensOf(group);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(group.scale);
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
